edits.replacement:
#root #keyslist .keysec{ color:var(--tx-1); }
/* v28.xx (cw-setnote) critic c-31 round 11 (Pad buttons 75 at 2: "an explaining sentence in a tinted bar at about 14px"; Settings 18 and 72 at 3: "the detail pane repeats Edit the words Off, which duplicates the focused row"; "its sentence is about 15px"). Now: the rebind callout is one short line at 20px with square corners, and the Settings detail pane shows only the row help line at 20px (the row above already wears the name and the value, so the pane drops its title and value, and hides when a row has no help). */
#root #keysnote{ clip-path:none; border-radius:var(--rad); font-size:var(--fs-body); }
#root #setdetail .sdk, #root #setdetail .sdv{ display:none; }
#root #setdetail:not(:has(.sdh)){ display:none; }
#root #setdetail{ min-height:0; }
#root #setdetail .sdh{ font-size:var(--fs-body); line-height:1.4; }

check:
{v:'VER',what:'the rebind callout is one short line without "ten seconds", and the Settings detail pane hides its repeated title and value',
 run:function(){
   var bad=[], el, t, d, k, h, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     el=document.createElement('div'); document.body.appendChild(el);
     PADB.waiting=0; padNoteShow(el); t=el.textContent; PADB.waiting=null;
     if(/ten seconds/i.test(t)) bad.push('the pad rebind callout still explains: '+t);
     if(/\.\s/.test(t)||/\.$/.test(t)) bad.push('the pad rebind callout is a sentence: '+t);
     KEYS.waiting=KEYS_ACTS[0][0]; keysNoteShow.call(null); KEYS.waiting=null;
     el.remove();
     document.body.classList.remove('padon');
     openSettings('display');
     if(typeof window.__setDetailSync==='function') window.__setDetailSync();
     d=document.getElementById('setdetail'); k=d&&d.querySelector('.sdk'); h=d&&d.querySelector('.sdh');
     if(k&&getComputedStyle(k).display!=='none') bad.push('the detail pane still repeats the row title');
     if(!d) bad.push('no detail pane');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ PADB.waiting=null; KEYS.waiting=null; var q=document.getElementById('settingsmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
